// QA-2 (resilience): security-boundary + concurrency regressions that the
// coder's contract tests do NOT cover:
//
//   - TestQA_SQLInjection — adversarial payloads through every string column of
//     CreateLibrary + PutItem are held as VALUES (parameterized placeholders),
//     never executed. The items/libraries tables survive; payloads round-trip
//     literally. The coder's store_test asserts parameterization by
//     construction; this asserts it under the canonical injection payloads.
//
//   - TestQA_Store_WAL_ConcurrentReadersDuringWrite — the WAL reader/writer
//     isolation invariant the coder omits: a single writer upserting the same
//     file_id repeatedly while N readers QueryItems concurrently. Readers never
//     error and never observe a duplicate/partial row (single-writer + WAL
//     snapshot); exactly one row remains. (The store is single-writer by
//     contract, arch §9.3 — multi-writer contention is out of scope, so this is
//     the correct concurrency property to assert.)
//
// The coder's run_test.go already proves scan ctx-cancellation and soft-fail
// aggregation, and manager_test.go proves the §7.3 restart/backoff state
// machine — those are NOT duplicated here (see the joint coverage map).
package mellifera_test

import (
	"context"
	"fmt"
	"sync"
	"sync/atomic"
	"testing"

	"github.com/mellifera/mellifera/internal/store"
)

// TestQA_SQLInjection is the S9 / AC-2 SQL-injection regression. Canonical
// injection payloads are passed through CreateLibrary (module_id, root_path,
// display_name) and PutItem (file_id, relative_path, media_type, document).
// Parameterized placeholders MUST hold each payload as a literal value, so: no
// table is dropped, the schema is intact, and the payload round-trips verbatim.
func TestQA_SQLInjection(t *testing.T) {
	ctx := context.Background()
	s := qaOpenStore(t)

	const (
		dropItems      = "tv'; DROP TABLE items;--"
		dropLibraries  = "x'; DROP TABLE libraries;--"
		unionPayload   = "tv' UNION SELECT sql FROM sqlite_master--;--"
		commentPayload = "media--; DROP"
	)

	qaRequireTable(t, s, "items")
	qaRequireTable(t, s, "libraries")

	libID, err := s.CreateLibrary(ctx, dropItems, unionPayload, commentPayload)
	if err != nil {
		t.Fatalf("CreateLibrary with injection payload errored (parameterization?): %v", err)
	}
	qaRequireTable(t, s, "items")
	qaRequireTable(t, s, "libraries")

	got, err := s.GetLibrary(ctx, libID)
	if err != nil {
		t.Fatalf("GetLibrary: %v", err)
	}
	if got.ModuleID != dropItems {
		t.Errorf("module_id = %q, want literal %q (parameterized value)", got.ModuleID, dropItems)
	}
	if got.RootPath != unionPayload {
		t.Errorf("root_path = %q, want literal %q", got.RootPath, unionPayload)
	}
	if got.DisplayName != commentPayload {
		t.Errorf("display_name = %q, want literal %q", got.DisplayName, commentPayload)
	}

	it := store.Item{
		ID: "qa-inj-item", ModuleID: dropItems, LibraryID: libID,
		FileID:        dropLibraries,
		RelativePath:  "'; DELETE FROM items WHERE 1=1;--",
		MediaType:     commentPayload,
		Document:      []byte(`{"ffprobe":{"injection":"'; DROP TABLE items;--"}}`),
		SchemaVersion: 1,
	}
	if err := s.PutItem(ctx, it); err != nil {
		t.Fatalf("PutItem with injection payload errored: %v", err)
	}
	qaRequireTable(t, s, "items")
	qaRequireTable(t, s, "libraries")

	back, err := s.GetItem(ctx, it.ID)
	if err != nil {
		t.Fatalf("GetItem: %v", err)
	}
	if back.FileID != dropLibraries {
		t.Errorf("file_id = %q, want literal %q", back.FileID, dropLibraries)
	}
	if back.MediaType != commentPayload {
		t.Errorf("media_type = %q, want literal %q", back.MediaType, commentPayload)
	}
	if n := qaItemCount(t, s, libID); n != 1 {
		t.Errorf("items for lib after injection = %d, want 1 (no DELETE executed)", n)
	}
}

// TestQA_Store_WAL_ConcurrentReadersDuringWrite is the WAL concurrency property
// (S4 / arch §9.3 single-writer + WAL snapshot isolation): one writer upserts
// the same file_id repeatedly while N readers QueryItems concurrently. Readers
// must never error and never see more than one row (the upsert key is unique);
// after the writer finishes there is exactly one row. This is the concurrency
// invariant the coder's single-threaded idempotency test does not exercise.
func TestQA_Store_WAL_ConcurrentReadersDuringWrite(t *testing.T) {
	ctx := context.Background()
	s := qaOpenStore(t)
	libID, err := s.CreateLibrary(ctx, "tv", "/qa/wal-concurrency", "QA WAL")
	if err != nil {
		t.Fatalf("CreateLibrary: %v", err)
	}

	const readers = 8
	stop := make(chan struct{})
	var readerErr atomic.Value // stores error

	var wg sync.WaitGroup
	// Single writer (store is single-writer by contract): repeated idempotent
	// upserts of one file_id with two document variants.
	wg.Add(1)
	go func() {
		defer wg.Done()
		for i := 0; i < 25; i++ {
			doc := []byte(`{"v":0}`)
			if i%2 == 1 {
				doc = []byte(`{"v":1}`)
			}
			it := store.Item{
				ID: "qa-wal-item", ModuleID: "tv", LibraryID: libID,
				FileID: "qa-same-file-id", RelativePath: "wal.mkv",
				MediaType: "tv", Document: doc, SchemaVersion: 1,
			}
			if perr := s.PutItem(ctx, it); perr != nil {
				readerErr.Store(perr.Error())
				close(stop)
				return
			}
		}
		close(stop)
	}()

	// Readers: concurrent QueryItems throughout the writes.
	for r := 0; r < readers; r++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				select {
				case <-stop:
					return
				default:
				}
				items, qerr := s.QueryItems(ctx, libID, 100, 0)
				if qerr != nil {
					readerErr.Store(qerr.Error())
					return
				}
				if len(items) > 1 {
					readerErr.Store(fmt.Sprintf("reader saw %d rows mid-write (upsert key violated)", len(items)))
					return
				}
			}
		}()
	}
	wg.Wait()

	if v := readerErr.Load(); v != nil {
		t.Fatalf("concurrent reader/writer failed: %v", v)
	}
	if n := qaItemCount(t, s, libID); n != 1 {
		t.Fatalf("after repeated idempotent upserts, items = %d, want exactly 1", n)
	}
}

// qaRequireTable fails the test if the named table is absent (a DROP executed).
func qaRequireTable(t *testing.T, s *store.Store, table string) {
	t.Helper()
	var name string
	err := s.DB().QueryRowContext(context.Background(),
		"SELECT name FROM sqlite_master WHERE type = ? AND name = ?", "table", table).Scan(&name)
	if err != nil {
		t.Fatalf("SQL injection regression: table %q is missing (a DROP must have executed): %v", table, err)
	}
}

func qaItemCount(t *testing.T, s *store.Store, libID int64) int {
	t.Helper()
	var n int
	if err := s.DB().QueryRowContext(context.Background(),
		"SELECT COUNT(*) FROM items WHERE library_id = ?", libID).Scan(&n); err != nil {
		t.Fatalf("count items: %v", err)
	}
	return n
}
